98	                () -> baggageService.load("LEG1",
99	                        new LoadRequest(UUID.randomUUID().toString(), 2, List.of("BAG2"))),
100	                () -> baggageService.seal("LEG1",
101	                        new SealRequest(UUID.randomUUID().toString(), 2)));
102	        List<Object> results = runConcurrently(tasks);
103	
104	        long successes = results.stream()
105	                .filter(r -> r instanceof LoadResponse || r instanceof SealResponse)
106	                .count();
107	        long conflicts = results.stream()
108	                .filter(ApiException.class::isInstance)
