119	        assertThat(version).isEqualTo(3);
120	        if ("OPEN".equals(status)) {
121	            // 装载先成功：封舱可随后以新版本完成，清单包含两件行李
122	            SealResponse sealed = baggageService.seal("LEG1",
123	                    new SealRequest(UUID.randomUUID().toString(), 3));
124	            assertThat(sealed.manifest()).containsExactly("BAG1", "BAG2");
125	        } else {
126	            // 封舱先成功：清单只有 BAG1，封舱后不得加装
127	            assertThat(status).isEqualTo("SEALED");
128	            assertThat(baggageService.getManifest("LEG1").manifest()).containsExactly("BAG1");
