141	                    new LoadRequest(requestId, 1, List.of("BAG1"))));
142	        }
143	        List<Object> results = runConcurrently(tasks);
144	
145	        assertThat(results).allSatisfy(result -> {
146	            assertThat(result).isInstanceOf(LoadResponse.class);
147	            assertThat(((LoadResponse) result).version()).isEqualTo(2);
148	        });
149	        Integer version = jdbcTemplate.queryForObject(
150	                "SELECT version FROM leg WHERE leg_id = 'LEG1'", Integer.class);
151	        assertThat(version).isEqualTo(2);
152	        Integer records = jdbcTemplate.queryForObject(
153	                "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG1'", Integer.class);
154	        assertThat(records).isEqualTo(1);
155	        Integer logs = jdbcTemplate.queryForObject(
156	                "SELECT COUNT(*) FROM request_log WHERE request_id = ?", Integer.class, requestId);
157	        assertThat(logs).isEqualTo(1);
158	    }
