169	    /** 同步起跑并发执行任务，结果按提交顺序返回（异常包装为返回值）。 */
170	    private List<Object> runConcurrently(List<Callable<Object>> tasks) throws Exception {
171	        CountDownLatch ready = new CountDownLatch(tasks.size());
172	        CountDownLatch start = new CountDownLatch(1);
173	        List<Future<Object>> futures = new ArrayList<>();
174	        for (Callable<Object> task : tasks) {
175	            futures.add(executor.submit(() -> {
176	                ready.countDown();
177	                assertThat(start.await(10, TimeUnit.SECONDS)).isTrue();
178	                try {
179	                    return task.call();
180	                } catch (ApiException ex) {
181	                    return ex;
182	                }
183	            }));
184	        }
185	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
186	        start.countDown();
187	        List<Object> results = new ArrayList<>();
188	        for (Future<Object> future : futures) {
189	            results.add(future.get(30, TimeUnit.SECONDS));
190	        }
191	        return results;
192	    }
193	}
