322	        load("LEG1", 1, List.of("BAG_SHORT"));
323	        seal("LEG1", 2);
324	        diffArrive("LEG1", 3, List.of()).andExpect(status().isOk());
325	
326	        // 整批包含一个短卸行李：422 且合法行李也不移动
327	        load("LEG2", 1, List.of("BAG_OK", "BAG_SHORT"))
328	                .andExpect(status().isUnprocessableEntity());
