331	                .andExpect(jsonPath("$.loadedLegId").doesNotExist())
332	                .andExpect(jsonPath("$.currentLocation").value("SHA"));
333	        mockMvc.perform(get("/api/legs/LEG2/manifest"))
334	                .andExpect(jsonPath("$.version").value(1))
335	                .andExpect(jsonPath("$.status").value("OPEN"));
336	        Integer records = jdbcTemplate.queryForObject(
337	                "SELECT COUNT(*) FROM load_record", Integer.class);
